88	
89	<script>
90	(function () {
91	  var WEEKDAYS = { 1: "周一", 2: "周二", 3: "周三", 4: "周四", 5: "周五", 6: "周六", 7: "周日" };
92	
93	  var form = document.getElementById("venue-form");
94	  var hoursRows = document.getElementById("hours-rows");
95	  var errorBox = document.getElementById("form-error");
96	  var listBox = document.getElementById("venue-list");
97	
98	  function showError(message) {
99	    errorBox.textContent = message;
100	    errorBox.style.display = "block";
101	  }
102	  function clearError() {
103	    errorBox.textContent = "";
104	    errorBox.style.display = "none";
105	  }
106	
107	  function addHourRow() {
108	    var row = document.createElement("div");
109	    row.className = "hour-row";
110	    var weekday = document.createElement("select");
111	    weekday.className = "hour-weekday";
112	    Object.keys(WEEKDAYS).forEach(function (d) {
113	      var opt = document.createElement("option");
114	      opt.value = d;
115	      opt.textContent = WEEKDAYS[d];
116	      weekday.appendChild(opt);
117	    });
118	    var start = document.createElement("input");
119	    start.type = "time"; start.className = "hour-start"; start.required = true;
120	    var dash = document.createElement("span");
121	    dash.textContent = "至";
122	    var end = document.createElement("input");
123	    end.type = "time"; end.className = "hour-end"; end.required = true;
124	    var remove = document.createElement("button");
125	    remove.type = "button";
126	    remove.className = "danger";
127	    remove.textContent = "删除";
128	    remove.addEventListener("click", function () { row.remove(); markFormDirty(); });
129	    row.appendChild(weekday);
130	    row.appendChild(start);
131	    row.appendChild(dash);
132	    row.appendChild(end);
133	    row.appendChild(remove);
134	    hoursRows.appendChild(row);
135	    markFormDirty();
136	  }
137	  document.getElementById("add-hour").addEventListener("click", addHourRow);
138	
139	  // 保存请求发出后到响应返回前，表单仍然允许编辑。用“脏标记”区分响应返回
140	  // 时表单是否已被用户动过：只有请求在途期间一次都没改过，成功后才执行既
141	  // 有的清空；一旦改过名称、容量、时区或增删改过时段行（哪怕后来又改回原
142	  // 值），成功响应只刷新列表，必须完整保留当前整份表单。
143	  var formDirty = false;
144	  var submitSequence = 0;
145	  function markFormDirty() { formDirty = true; }
146	  ["name", "capacity", "timezone"].forEach(function (id) {
147	    document.getElementById(id).addEventListener("input", markFormDirty);
148	  });
149	  // 时段行是动态添加的，输入与星期选择在容器上统一捕获；新增/删除行在
150	  // addHourRow 内单独标记。
151	  hoursRows.addEventListener("input", markFormDirty);
152	  hoursRows.addEventListener("change", markFormDirty);
153	
154	  function collectHours() {
155	    var rows = hoursRows.querySelectorAll(".hour-row");
156	    var hours = [];
157	    for (var i = 0; i < rows.length; i++) {
158	      var weekday = parseInt(rows[i].querySelector(".hour-weekday").value, 10);
159	      var start = rows[i].querySelector(".hour-start").value;
160	      var end = rows[i].querySelector(".hour-end").value;
161	      if (!start || !end) {
162	        return { error: "第 " + (i + 1) + " 个开放时段未填写完整，请补全或删除该时段。" };
163	      }
164	      hours.push({ weekday: weekday, start: start, end: end });
165	    }
166	    return { hours: hours };
167	  }
168	
169	  function toMinutes(hhmm) {
170	    var parts = hhmm.split(":");
171	    return parseInt(parts[0], 10) * 60 + parseInt(parts[1], 10);
172	  }
173	
174	  function escapeHTML(value) {
175	    return String(value).replace(/[&<>"']/g, function (c) {
176	      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
177	    });
178	  }
179	
180	  // canonicalDigits 按十进制原文校验容量输入：只接受由数字组成的正整数，
181	  // 返回去掉前导零后的数字原文；为空、为零或包含负号、小数点等内容时返回
182	  // null。全程不经过 Number/parseInt，否则 9007199254740993 这样超过
183	  // Number.MAX_SAFE_INTEGER 的值会被悄悄舍入成相邻整数。
184	  function canonicalDigits(raw) {
185	    if (!/^\d+$/.test(raw)) return null;
186	    var digits = raw.replace(/^0+/, "");
187	    if (digits === "") return null; // 全是 0：容量为零，不接受
188	    return digits;
189	  }
190	
191	  // buildVenueRequestBody 直接拼接 JSON 文本，让容量以输入的十进制数字原文
192	  // 发送：不能用 JSON.stringify({capacity: 数字})，大整数在转成 Number 时
193	  // 已经被舍入，stringify 只会写回错误的值。名称、时区是字符串，交给
194	  // JSON.stringify 转义；传输报文中 capacity 仍是 JSON 数字。
195	  function buildVenueRequestBody(name, capacityDigits, timezone, hours) {
196	    return "{" +
197	      '"name":' + JSON.stringify(name) +
198	      ',"capacity":' + capacityDigits +
199	      ',"timezone":' + JSON.stringify(timezone) +
200	      ',"weeklyHours":' + JSON.stringify(hours) +
201	      "}";
202	  }
203	
204	  // parseVenuesJSON 解析场地列表，但保留 capacity 数字的十进制原文：
205	  // JSON.parse 会把数字存成 float64，超过 2^53 的容量会被舍入成相邻整数。
206	  // 这里逐字符扫描 JSON（正确处理字符串内的转义引号），仅当 "capacity"
207	  // 作为对象键出现时，把其后数字的原文包成字符串，页面拿到的就是服务端
208	  // 逐位发出的完整十进制数字（服务端只输出普通整数，不会出现科学计数法）。
209	  // 名称等其它字段一律原样复制，绝不改写；线上传输的 JSON 中 capacity
210	  // 仍是数字，接口格式不变。
211	  function parseVenuesJSON(text) {
212	    var out = "", i = 0, n = text.length;
213	    while (i < n) {
214	      if (text[i] !== '"') {
215	        out += text[i];
216	        i++;
217	        continue;
218	      }
219	      // 读取完整字符串，跳过转义字符，使名称中出现的 \"capacity\":1
220	      // 之类文本不会被误认为对象键。
221	      var tokenStart = i, j = i + 1;
222	      while (j < n) {
223	        if (text[j] === "\\") { j += 2; continue; }
224	        if (text[j] === '"') { j++; break; }
225	        j++;
226	      }
227	      var token = text.slice(tokenStart, j);
228	      // 对象键后面（允许空白）必然是 ':'；字符串值后面只能是 ',' 或 '}'。
229	      var k = j;
230	      while (k < n && /\s/.test(text[k])) k++;
231	      if (text[k] !== ":" || JSON.parse(token) !== "capacity") {
232	        out += token;
233	        i = j;
234	        continue;
235	      }
236	      // 复制到 ':' 之后（含中间空白），再把数字原文引用为字符串。
237	      out += token + text.slice(j, k + 1);
238	      var p = k + 1;
239	      while (p < n && /\s/.test(text[p])) { out += text[p]; p++; }
240	      var numStart = p;
241	      while (p < n && /[-+0-9eE.]/.test(text[p])) p++;
242	      out += JSON.stringify(text.slice(numStart, p));
243	      i = p;
244	    }
245	    return JSON.parse(out);
246	  }
