248	  function renderVenues(venues) {
249	    if (!venues.length) {
250	      listBox.innerHTML = '<div class="empty">还没有场地记录。</div>';
251	      return;
252	    }
253	    var sortedHours = function (hours) {
254	      return hours.slice().sort(function (a, b) {
255	        if (a.weekday !== b.weekday) return a.weekday - b.weekday;
256	        return toMinutes(a.start) - toMinutes(b.start);
257	      });
258	    };
259	    listBox.innerHTML = venues.map(function (venue) {
