229	// ---- POST 挂起闸门（Fetch 域拦截）----
230	
231	// createPostGate 用 CDP 的 Fetch 域把发往 /api/venues 的 POST 暂停在“请求
232	// 已经发出、响应尚未返回”的阶段，真实复现“点击保存后、结果返回前继续编辑
233	// 表单”的等待窗口：pause() 之后遇到的下一个场地 POST 会被挂起，测试先在
234	// 页面里完成编辑，再决定放行到真实服务端（pass）或直接合成响应（fulfill，
235	// 例如 400），响应内容与到达时机完全由测试掌握。列表 GET 等其余请求一律
236	// 立即放行，不改变页面与服务端的既有行为。
237	function createPostGate(cdp) {
238	  // held: id -> { id, requestId, url, body, done }
239	  const held = new Map();
240	  let seq = 0;
241	  let paused = false;
242	  let waiters = [];
243	
244	  cdp.on((method, params) => {
245	    if (method !== "Fetch.requestPaused") return;
246	    // 监听器内的异步失败（例如请求已失效）绝不能冒泡成 unhandledRejection，
247	    // 统一吞掉：挂起/放行失败只会让对应场景的断言失败。
248	    (async () => {
249	      const isVenuePost = params.request && params.request.method === "POST" &&
250	        params.request.url.includes("/api/venues");
251	      if (!paused || !isVenuePost) {
252	        try {
253	          await cdp.send("Fetch.continueRequest", { requestId: params.requestId });
254	        } catch { /* 请求可能已失效，忽略 */ }
255	        return;
256	      }
257	      // 挂起时立即取回请求体原文：此时尚未放行，内容必然是点击保存那一刻的
258	      // 快照，之后页面怎么改都影响不到它。
259	      let body = null;
260	      try {
261	        const out = await cdp.send("Fetch.getRequestBody", { requestId: params.requestId });
