542	async function poll(fn, { timeout = 6000, interval = 80, label = "" } = {}) {
543	  const deadline = Date.now() + timeout;
544	  let lastErr;
545	  while (Date.now() < deadline) {
546	    try {
547	      const v = await fn();
548	      if (v) return v;
549	    } catch (e) { lastErr = e; }
550	    await sleep(interval);
551	  }
552	  throw new Error(`等待页面状态超时${label ? "（" + label + "）" : ""}${lastErr ? ": " + lastErr.message : ""}`);
553	}
