        check(S, "失败请求仍按未舍入的原文提交", token === tooBig, `token=${token} body=${raw}`);
        check(S, "失败请求容量仍是数字而非字符串", token !== null && token[0] !== '"', token);
        check(S, "服务端返回 400", post.status === 400, `status=${post.status}`);

