    // ---------- 场景 6：跨午夜相接时段保存成功，卡片排序、次日标注与时区 ----------
    {
      const S = "开放时段跨午夜相接与卡片展示";
      const name = "夜训馆";
      const tz = "Asia/Shanghai";
      // 严格按题目给定顺序填写：周日 22:00-02:00、周一 09:00-12:00、周一 02:00-04:00。
      const hours = [
        { weekday: 7, start: "22:00", end: "02:00" },
