1	package main
2	
3	import (
4		"context"
5		_ "embed"
6		"encoding/json"
7		"errors"
8		"flag"
9		"fmt"
10		"io"
11		"net"
12		"net/http"
13		"os"
14		"os/signal"
15		"syscall"
16		"time"
17	)
18	
19	const product = "VenueBook"
20	const resourceName = "venues"
21	
22	//go:embed index.html
23	var page string
24	
25	func writeJSON(w http.ResponseWriter, status int, value any) {
26		w.Header().Set("Content-Type", "application/json; charset=utf-8")
27		w.WriteHeader(status)
28		_ = json.NewEncoder(w).Encode(value)
29	}
30	
31	func errorJSON(w http.ResponseWriter, status int, message string) {
32		writeJSON(w, status, map[string]string{"error": message})
33	}
34	
35	// allowedMethods 列出每个已知路径实际支持的方法。
36	var allowedMethods = map[string]string{
37		"/":           "GET",
38		"/health":     "GET",
39		"/api/venues": "GET, POST",
40	}
41	
42	func run() error {
43		if len(os.Args) < 2 {
44			printHelp()
45			return errors.New("expected serve or --help")
46		}
47		if os.Args[1] == "--help" || os.Args[1] == "-h" {
48			printHelp()
49			return nil
50		}
51		if os.Args[1] != "serve" {
52			return errors.New("expected serve or --help")
53		}
54		args := flag.NewFlagSet("venue-book serve", flag.ContinueOnError)
55		args.SetOutput(os.Stdout)
56		host := args.String("host", "127.0.0.1", "address to bind")
57		port := args.Int("port", 8080, "port to bind; 0 selects an available port")
58		data := args.String("data-dir", "data", "directory for local records")
59		if err := args.Parse(os.Args[2:]); errors.Is(err, flag.ErrHelp) {
60			return nil
61		} else if err != nil {
62			return err
63		}
64		if args.NArg() != 0 {
65			return errors.New("unexpected positional argument")
66		}
67		if *port < 0 || *port > 65535 {
68			return errors.New("port must be between 0 and 65535")
69		}
70		records, err := newStore(*data)
71		if err != nil {
72			return err
73		}
74		server := &http.Server{
75			ReadHeaderTimeout: 5 * time.Second,
76			Handler:           newHandler(records),
77		}
78		listener, err := net.Listen("tcp", net.JoinHostPort(*host, fmt.Sprint(*port)))
79		if err != nil {
80			return err
81		}
82		fmt.Printf("%s listening on http://%s\n", product, listener.Addr().String())
83		ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
84		defer stop()
85		failures := make(chan error, 1)
86		go func() { failures <- server.Serve(listener) }()
87		select {
88		case err := <-failures:
89			if !errors.Is(err, http.ErrServerClosed) {
90				return err
91			}
92		case <-ctx.Done():
93			shutdown, cancel := context.WithTimeout(context.Background(), 3*time.Second)
94			defer cancel()
95			if err := server.Shutdown(shutdown); err != nil {
96				return err
97			}
98		}
99		return nil
100	}
101	
102	func newHandler(records *store) http.Handler {
103		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
104			route := r.URL.Path
105			allow, known := allowedMethods[route]
106			if !known {
107				errorJSON(w, http.StatusNotFound, "not found")
108				return
109			}
110			if route == "/api/venues" {
111				switch r.Method {
112				case http.MethodGet:
113					handleListVenues(w, r, records)
114					return
115				case http.MethodPost:
116					handleCreateVenue(w, r, records)
117					return
118				default:
119					w.Header().Set("Allow", allow)
120					errorJSON(w, http.StatusMethodNotAllowed, "method not allowed")
121					return
122				}
123			}
124			if r.Method != http.MethodGet {
125				w.Header().Set("Allow", allow)
126				errorJSON(w, http.StatusMethodNotAllowed, "method not allowed")
127				return
128			}
129			if route == "/" {
130				w.Header().Set("Content-Type", "text/html; charset=utf-8")
131				_, _ = fmt.Fprint(w, page)
132				return
133			}
134			// /health
135			writeJSON(w, http.StatusOK, map[string]string{"status": "ok", "product": product})
136		})
137	}
138	
139	func handleListVenues(w http.ResponseWriter, _ *http.Request, records *store) {
140		venues, err := records.list()
141		if err != nil {
142			// 读不到或数据损坏时返回 500，绝不能回写空列表覆盖已有记录。
143			errorJSON(w, http.StatusInternalServerError, "unable to read venues")
144			return
145		}
146		writeJSON(w, http.StatusOK, map[string]any{resourceName: venues})
147	}
148	
149	func handleCreateVenue(w http.ResponseWriter, r *http.Request, records *store) {
150		// 限制请求体大小，避免异常大请求占用内存。
