1	package main
2	
3	import (
4		"crypto/rand"
5		"encoding/hex"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"math"
10		"math/big"
11		"os"
12		"path/filepath"
13		"sort"
14		"strconv"
15		"strings"
16		"sync"
17		"time"
18	
19		// 内嵌时区数据库，保证在没有 /usr/share/zoneinfo 的环境中也能校验 IANA 时区。
20		_ "time/tzdata"
21	)
22	
23	// maxVenueCapacity 是容量字段支持的整数上限。容量表示人数，必须能在
24	// 请求、保存和响应中逐位准确表示，因此范围限定在本机 int 可容纳的区间内
25	// （64 位平台上即 int64 上限）。
26	const maxVenueCapacity = int64(^uint(0) >> 1)
27	
28	// WeeklyHour 表示每周固定的一段开放时间。
29	// Weekday 用 1 到 7 表示周一至周日；Start/End 为 HH:mm。
30	// End 晚于 Start 表示当天结束，早于 Start 表示次日结束。
31	type WeeklyHour struct {
32		Weekday int    `json:"weekday"`
33		Start   string `json:"start"`
34		End     string `json:"end"`
35	}
36	
37	// Venue 是一条场地记录。
38	type Venue struct {
39		ID          string       `json:"id"`
40		Name        string       `json:"name"`
41		Capacity    int          `json:"capacity"`
42		Timezone    string       `json:"timezone"`
43		WeeklyHours []WeeklyHour `json:"weeklyHours"`
44	}
45	
46	// apiError 是返回给客户端的校验错误（HTTP 400）。
47	type apiError struct{ msg string }
48	
49	func (e *apiError) Error() string { return e.msg }
50	
51	func badRequest(format string, args ...any) error {
52		return &apiError{msg: fmt.Sprintf(format, args...)}
53	}
54	
55	// store 负责场地记录的持久化，所有访问都通过互斥锁串行化。
56	type store struct {
57		mu   sync.Mutex
58		path string
59	}
60	
61	func newStore(dataDir string) (*store, error) {
62		if err := os.MkdirAll(dataDir, 0700); err != nil {
63			return nil, err
64		}
65		path := filepath.Join(dataDir, "venues.json")
66		// 全新数据目录时初始化为空数组，保持原有行为。
67		file, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600)
68		if err == nil {
69			if _, err := file.WriteString("[]\n"); err != nil {
70				_ = file.Close()
71				return nil, err
72			}
73			if err := file.Close(); err != nil {
74				return nil, err
75			}
76		} else if !errors.Is(err, os.ErrExist) {
77			return nil, err
78		}
79		return &store{path: path}, nil
80	}
81	
82	// load 读取并解析全部记录。读不到、JSON 损坏、结构异常或任一场地的
83	// 开放时段不合法都返回错误，调用方必须按 500 处理，绝不能把错误数据
84	// 当作空列表覆盖，也不能跳过异常场地只返回剩余记录。
85	func (s *store) load() ([]Venue, error) {
86		raw, err := os.ReadFile(s.path)
87		if err != nil {
88			return nil, err
89		}
90		var venues []Venue
91		if err := json.Unmarshal(raw, &venues); err != nil {
92			return nil, fmt.Errorf("venues data is corrupted: %w", err)
93		}
94		if venues == nil {
95			venues = []Venue{}
96		}
97		for i := range venues {
98			// 兼容旧数据：字段缺省或为 null 仍按空数组（暂未开放）读取。
99			if venues[i].WeeklyHours == nil {
100				venues[i].WeeklyHours = []WeeklyHour{}
101			}
102			// 已保存数据同样必须满足新增时的全部时段规则；任一非法即视为损坏。
103			if err := validateHours(venues[i].WeeklyHours); err != nil {
104				return nil, fmt.Errorf("venues data is corrupted: venue %q has invalid weekly hours: %w", venues[i].ID, err)
105			}
106		}
107		return venues, nil
108	}
109	
110	// save 通过同目录临时文件 + 重命名原子写入，避免半写状态损坏数据。
111	func (s *store) save(venues []Venue) error {
112		encoded, err := json.MarshalIndent(venues, "", "  ")
113		if err != nil {
114			return err
115		}
116		encoded = append(encoded, '\n')
117		dir := filepath.Dir(s.path)
118		tmp, err := os.CreateTemp(dir, ".venues-*.tmp")
119		if err != nil {
120			return err
121		}
122		tmpName := tmp.Name()
123		defer os.Remove(tmpName)
124		if _, err := tmp.Write(encoded); err != nil {
125			_ = tmp.Close()
126			return err
127		}
128		if err := tmp.Close(); err != nil {
129			return err
130		}
131		if err := os.Chmod(tmpName, 0600); err != nil {
132			return err
133		}
134		return os.Rename(tmpName, s.path)
135	}
136	
137	// list 返回当前全部场地（按首次创建顺序保留）。
138	func (s *store) list() ([]Venue, error) {
139		s.mu.Lock()
140		defer s.mu.Unlock()
141		return s.load()
142	}
143	
144	// create 校验请求内容，通过后写入新记录并返回保存后的场地。
145	// 校验失败时返回 apiError（400），不会写入任何内容。
146	func (s *store) create(payload map[string]any) (Venue, error) {
147		s.mu.Lock()
148		defer s.mu.Unlock()
149	
150		venues, err := s.load()
151		if err != nil {
152			return Venue{}, err
153		}
154	
155		venue, err := buildVenue(payload)
156		if err != nil {
157			return Venue{}, err
158		}
159	
160		venue.ID = newID()
161		for idTaken(venues, venue.ID) {
162			// 极小概率的随机碰撞：重新生成直到唯一。
163			venue.ID = newID()
164		}
165		venues = append(venues, venue)
166		if err := s.save(venues); err != nil {
167			return Venue{}, err
168		}
169		return venue, nil
170	}
171	
172	// buildVenue 对请求对象做逐字段严格校验。
173	func buildVenue(payload map[string]any) (Venue, error) {
174		name, err := requireString(payload, "name")
175		if err != nil {
176			return Venue{}, err
177		}
178		name = strings.TrimSpace(name)
179		if name == "" {
180			return Venue{}, badRequest("name 去除首尾空白后不能为空")
181		}
182	
183		capacity, err := requirePositiveInt(payload, "capacity")
184		if err != nil {
185			return Venue{}, err
186		}
187	
188		timezone, err := requireString(payload, "timezone")
189		if err != nil {
190			return Venue{}, err
191		}
192		if timezone == "" || timezone == "Local" {
193			return Venue{}, badRequest("timezone 必须是有效的 IANA 时区名称，例如 Asia/Shanghai")
194		}
195		if _, err := time.LoadLocation(timezone); err != nil {
196			return Venue{}, badRequest("timezone 必须是有效的 IANA 时区名称，例如 Asia/Shanghai")
197		}
198	
199		rawHours, ok := payload["weeklyHours"]
200		if !ok {
201			return Venue{}, badRequest("缺少 weeklyHours 字段")
202		}
203		hours, err := parseWeeklyHours(rawHours)
204		if err != nil {
205			return Venue{}, err
206		}
207		if err := validateHours(hours); err != nil {
208			// 读取已保存数据时 validateHours 的错误按数据损坏（500）处理；
209			// 这里是新增请求，包装成面向客户端的 400 校验错误。
210			return Venue{}, badRequest("%s", err.Error())
211		}
212	
213		return Venue{
214			Name:        name,
215			Capacity:    capacity,
216			Timezone:    timezone,
217			WeeklyHours: hours,
218		}, nil
219	}
220	
221	func missingOrWrong(field, kind string) error {
222		return badRequest("%s 类型错误：应为%s", field, kind)
223	}
224	
225	func requireString(payload map[string]any, field string) (string, error) {
226		value, ok := payload[field]
227		if !ok || value == nil {
228			return "", missingOrWrong(field, "字符串")
229		}
230		str, ok := value.(string)
231		if !ok {
232			return "", missingOrWrong(field, "字符串")
233		}
234		return str, nil
235	}
236	
237	// parseJSONInteger 按 JSON 数字的准确十进制文本判断它是否为整数，并返回其
238	// 精确值。value 必须来自开启了 UseNumber 的 JSON 解码（即 json.Number），
239	// 这样即使是 9007199254740993 这样超过 float64 安全整数范围、或
240	// 120.00000000000000001 这样带极小小数的数字，也不会在转换中被悄悄舍入。
241	//
242	// 返回值含义：
243	//   - isInt=false：不是 JSON 整数（根本不是数字，或带有非零小数部分）；
244	//   - isInt=true、inRange=true：z 是精确的整数值，且能放进 int64；
245	//   - isInt=true、inRange=false：确实是整数，但超出 int64 可表示范围，
246	//     此时 z 为 nil，sign 仍标明它是正数还是负数。
247	//
248	// 120、120.0、1.2e2 都得到整数 120；120.00000000000000001 和 1e-1 则带
249	// 小数部分，判定为非整数。
250	func parseJSONInteger(value any) (z *big.Int, sign int, isInt bool, inRange bool) {
251		switch number := value.(type) {
252		case json.Number:
253			return parseIntegerText(string(number))
254		case float64:
255			// 兼容直接在进程内构造 map（如测试）的调用方。HTTP 入口已启用
256			// UseNumber，不会走到这里；此处能看到的只有调用方手中的 float64，
257			// 按其当前值做精确的整数判断即可。
258			if math.IsNaN(number) || math.IsInf(number, 0) || number != math.Trunc(number) {
259				return nil, 0, false, false
260			}
261			sig := 1
262			switch {
263			case number < 0:
264				sig = -1
265			case number == 0:
266				sig = 0
267			}
268			// 用严格的 2^63 边界比较，避免 float64(math.MaxInt64) 进位到 2^63
269			// 后再转 int64 发生溢出回绕。
270			if number < -9223372036854775808.0 || number >= 9223372036854775808.0 {
271				return nil, sig, true, false
272			}
273			n := int64(number)
274			return big.NewInt(n), sig, true, true
275		default:
276			return nil, 0, false, false
277		}
278	}
279	
280	// parseIntegerText 按 JSON 数字的原始十进制文本做精确解析，逻辑见
281	// parseJSONInteger 的说明。
282	func parseIntegerText(text string) (z *big.Int, sign int, isInt bool, inRange bool) {
283		mant, exp, ok := decimalNumber(text)
284		if !ok {
285			return nil, 0, false, false
286		}
287		if mant.Sign() == 0 {
288			// 0、0.0、0e10 等都精确等于整数 0。
289			return big.NewInt(0), 0, true, true
290		}
291		// 极大/极小指数下无需真的构造巨大整数：非零尾数乘 10^exp 必然超出
292		// int64；非零数除以足够大的 10 的幂必然留下小数部分。
293		switch {
294		case exp > 100000:
295			return nil, mant.Sign(), true, false
296		case exp < -100000:
297			return nil, mant.Sign(), false, false
298		}
299		z = new(big.Int).Set(mant)
300		if exp >= 0 {
301			z.Mul(z, new(big.Int).Exp(big.NewInt(10), big.NewInt(exp), nil))
302		} else {
303			divisor := new(big.Int).Exp(big.NewInt(10), big.NewInt(-exp), nil)
304			abs := new(big.Int).Set(z)
305			if abs.Sign() < 0 {
306				abs.Neg(abs)
307			}
308			// 不能被 10^(-exp) 整除，说明小数点后存在非零数字，不是整数。
309			if new(big.Int).Mod(abs, divisor).Sign() != 0 {
310				return nil, mant.Sign(), false, false
311			}
312			z.Quo(z, divisor)
313		}
314		if !z.IsInt64() {
315			return nil, z.Sign(), true, false
316		}
317		return z, z.Sign(), true, true
318	}
319	
320	// decimalNumber 把 JSON 数字文本拆成带符号的整数尾数 m 与十进制指数 e，
321	// 使 原值 == m * 10^e。输入来自合法 JSON 解码，不接受 Infinity/NaN。
322	func decimalNumber(text string) (m *big.Int, e int64, ok bool) {
323		s := text
324		neg := false
325		if len(s) > 0 && (s[0] == '+' || s[0] == '-') {
326			neg = s[0] == '-'
327			s = s[1:]
328		}
329		if s == "" {
330			return nil, 0, false
331		}
332		rest, expText, hasExp := s, "", false
333		if i := strings.IndexAny(s, "eE"); i >= 0 {
334			rest, expText, hasExp = s[:i], s[i+1:], true
335		}
336		body := rest
337		if i := strings.IndexByte(rest, '.'); i >= 0 {
338			whole, frac := rest[:i], rest[i+1:]
339			if frac == "" {
340				return nil, 0, false // 如 "1."，不是合法 JSON 数字
341			}
342			body = whole + frac
343			e = -int64(len(frac))
344		}
345		if body == "" || !isDigits(body) {
346			return nil, 0, false
347		}
348		if hasExp {
349			exp, err := strconv.ParseInt(expText, 10, 64)
350			if err != nil {
351				return nil, 0, false
352			}
353			e += exp
354		}
355		m, ok = new(big.Int).SetString(body, 10)
356		if !ok {
357			return nil, 0, false
358		}
359		if neg {
360			m.Neg(m)
361		}
362		return m, e, true
363	}
364	
365	func isDigits(s string) bool {
366		if s == "" {
367			return false
368		}
369		for i := 0; i < len(s); i++ {
370			if s[i] < '0' || s[i] > '9' {
371				return false
372			}
373		}
374		return true
375	}
376	
377	// requirePositiveInt 校验表示人数的容量字段：必须是 JSON 数字、按准确数值
378	// 判断为正整数，且落在支持的整数范围内。任何非正整数（零、负数以及带小数
379	// 部分的数字）都返回“必须是正整数”；是整数但超出范围则返回“超出支持范围”，
380	// 绝不截断或舍入成相邻整数保存。
381	func requirePositiveInt(payload map[string]any, field string) (int, error) {
382		value, ok := payload[field]
383		if !ok || value == nil {
384			return 0, missingOrWrong(field, "正整数")
385		}
386		z, sign, isInt, inRange := parseJSONInteger(value)
387		if !isInt || sign <= 0 {
388			return 0, missingOrWrong(field, "正整数")
389		}
390		if !inRange || z.Int64() > maxVenueCapacity {
391			return 0, badRequest("%s 超出支持范围：容量必须是 1 到 %d 的整数", field, maxVenueCapacity)
392		}
393		return int(z.Int64()), nil
394	}
395	
396	// requireWeekday 用与容量相同的精确文本解析星期字段，保证只接受 1 到 7 的
397	// 整数（1.5 这类带小数的值不会被舍入后接受）。
398	func requireWeekday(value any, i int) (int, error) {
399		z, _, isInt, inRange := parseJSONInteger(value)
400		if !isInt {
401			return 0, badRequest("weeklyHours[%d].weekday 类型错误：应为 1 到 7 的整数", i)
402		}
403		if !inRange || z.Int64() < 1 || z.Int64() > 7 {
404			return 0, badRequest("weeklyHours[%d].weekday 必须为 1 到 7（周一至周日）", i)
405		}
406		return int(z.Int64()), nil
407	}
408	
409	func parseWeeklyHours(raw any) ([]WeeklyHour, error) {
410		if raw == nil {
411			return nil, badRequest("weeklyHours 类型错误：应为数组")
412		}
413		items, ok := raw.([]any)
414		if !ok {
415			return nil, badRequest("weeklyHours 类型错误：应为数组")
416		}
417		hours := make([]WeeklyHour, 0, len(items))
418		for i, item := range items {
419			obj, ok := item.(map[string]any)
420			if !ok || obj == nil {
421				return nil, badRequest("weeklyHours[%d] 类型错误：应为对象", i)
422			}
423			rawWeekday, ok := obj["weekday"]
424			if !ok || rawWeekday == nil {
425				return nil, badRequest("weeklyHours[%d].weekday 类型错误：应为 1 到 7 的整数", i)
426			}
427			weekday, err := requireWeekday(rawWeekday, i)
428			if err != nil {
429				return nil, err
430			}
431			start, err := hourField(obj, i, "start")
432			if err != nil {
433				return nil, err
434			}
435			end, err := hourField(obj, i, "end")
436			if err != nil {
437				return nil, err
438			}
439			hours = append(hours, WeeklyHour{Weekday: weekday, Start: start, End: end})
440		}
441		return hours, nil
442	}
443	
444	func hourField(obj map[string]any, i int, field string) (string, error) {
445		value, ok := obj[field]
446		if !ok || value == nil {
447			return "", badRequest("weeklyHours[%d].%s 类型错误：应为 HH:mm 时间", i, field)
448		}
449		str, ok := value.(string)
450		if !ok || !validHHMM(str) {
451			return "", badRequest("weeklyHours[%d].%s 时间无效，必须为 00:00 至 23:59 的 HH:mm 格式", i, field)
452		}
453		return str, nil
454	}
455	
456	// validHHMM 严格校验 HH:mm：两位小时、冒号、两位分钟，范围 00:00–23:59。
457	func validHHMM(value string) bool {
458		if len(value) != 5 || value[2] != ':' {
459			return false
460		}
461		for i, c := range value {
462			if i == 2 {
463				continue
464			}
465			if c < '0' || c > '9' {
466				return false
467			}
468		}
469		hour := int(value[0]-'0')*10 + int(value[1]-'0')
470		minute := int(value[3]-'0')*10 + int(value[4]-'0')
471		return hour <= 23 && minute <= 59
472	}
473	
474	func minutes(value string) int {
475		return int(value[0]-'0')*600 + int(value[1]-'0')*60 +
476			int(value[3]-'0')*10 + int(value[4]-'0')
477	}
478	
479	// interval 是展开到周时间轴上的一段开放时间，单位为分钟。
480	// 周一 00:00 为起点 0。
481	type interval struct {
482		start int
483		end   int
484		label string
485	}
486	
487	// validateHours 按开放时段的业务规则检查一段已解析的时段数据。
488	// 规则同时用于新增请求（400 校验）和已保存数据（损坏时按 500 处理）：
489	// 星期为 1–7（周一至周日），时间为严格 HH:mm（00:00–23:59），
490	// 起止时间不能相同；结束早于开始表示次日结束。重叠判断覆盖跨午夜
491	// 延续到次日的部分，也包含周日延续到下周一的部分；部分重叠、完全
492	// 包含和重复时段都不合法，下一段恰好在前一段结束时开始合法。
493	// 时段的填写顺序不影响结果。
494	//
495	// 返回的是普通错误而非 apiError：读取已保存数据命中时按数据损坏（500）
496	// 处理；新增流程由 buildVenue 包装成面向客户端的 400 错误。
497	func validateHours(hours []WeeklyHour) error {
498		intervals := make([]interval, 0, len(hours)*2)
499		for _, h := range hours {
500			if h.Weekday < 1 || h.Weekday > 7 {
501				return fmt.Errorf("开放时段无效：星期 %d 不在 1 到 7（周一至周日）范围内", h.Weekday)
502			}
503			if !validHHMM(h.Start) || !validHHMM(h.End) {
504				return fmt.Errorf("开放时段无效：%s 的时间 %s-%s 不是合法的 HH:mm", weekdayName(h.Weekday), h.Start, h.End)
505			}
506			startMin := minutes(h.Start)
507			endMin := minutes(h.End)
508			label := fmt.Sprintf("%s %s-%s", weekdayName(h.Weekday), h.Start, h.End)
509			if startMin == endMin {
510				return fmt.Errorf("开放时段无效：%s 的结束时间与开始时间相同", label)
511			}
512			start := (h.Weekday-1)*1440 + startMin
513			end := (h.Weekday-1)*1440 + endMin
514			if endMin < startMin {
515				end += 1440 // 跨午夜，次日结束
516			}
517			intervals = append(intervals, interval{start: start, end: end, label: label})
518		}
519		// 复制到下一周，用于检测周日跨午夜与下周一时段相交。
520		base := make([]interval, len(intervals))
521		copy(base, intervals)
522		for _, iv := range base {
523			intervals = append(intervals, interval{
524				start: iv.start + 7*1440,
525				end:   iv.end + 7*1440,
526				label: iv.label,
527			})
528		}
529		sort.Slice(intervals, func(i, j int) bool {
530			if intervals[i].start != intervals[j].start {
531				return intervals[i].start < intervals[j].start
532			}
533			return intervals[i].end < intervals[j].end
534		})
535		for i := 1; i < len(intervals); i++ {
536			if intervals[i].start < intervals[i-1].end {
537				return fmt.Errorf("开放时段存在相交：%s 与其他时段重叠", intervals[i].label)
538			}
539		}
540		return nil
541	}
542	
543	func weekdayName(weekday int) string {
544		return [...]string{"", "周一", "周二", "周三", "周四", "周五", "周六", "周日"}[weekday]
545	}
546	
547	// newID 生成非空、概率上唯一的记录标识。
548	func newID() string {
549		b := make([]byte, 16)
550		if _, err := rand.Read(b); err != nil {
551			// crypto/rand 失败极不寻常；退化为纳秒时间戳，仍保证非空且基本唯一。
552			return fmt.Sprintf("v-%d", time.Now().UnixNano())
553		}
554		return hex.EncodeToString(b)
555	}
556	
557	func idTaken(venues []Venue, id string) bool {
558		for _, v := range venues {
559			if v.ID == id {
560				return true
561			}
562		}
563		return false
564	}
565

