// ---- Fetch 闸门（Fetch 域拦截，POST 与 GET 各一把）----

// createPostGate 用 CDP 的 Fetch 域把发往 /api/venues 的 POST 暂停在“请求
// 已经发出、响应尚未返回”的阶段，真实复现“点击保存后、结果返回前继续编辑
// 表单”的等待窗口：pause() 之后遇到的下一个场地 POST 会被挂起，测试先在
// 页面里完成编辑，再决定放行到真实服务端（pass）或直接合成响应（fulfill，
// 例如 400），响应内容与到达时机完全由测试掌握。
//
// createGetGate 同样挂起场地列表 GET，用于复现“读取交错”：页面打开时的
// 初次读取尚未结束，保存成功又触发一次较新的读取。两次 GET 各自可被放行
// （pass，到真实服务端）、直接合成响应（fulfill：HTTP 错误、无法解析的
// JSON）或制造连接失败（fail），返回内容与先后顺序完全由测试掌握。其余
// 请求（HTML、POST 等）一律立即放行，不改变页面与服务端的既有行为。
function createApiGate(cdp, method) {
  // held: id -> { id, requestId, url, body, done }
  const held = new Map();
  let seq = 0;
  let paused = false;
  let waiters = [];

  cdp.on((methodEvent, params) => {
    if (methodEvent !== "Fetch.requestPaused") return;
    // 监听器内的异步失败（例如请求已失效）绝不能冒泡成 unhandledRejection，
    // 统一吞掉：挂起/放行失败只会让对应场景的断言失败。
    (async () => {
      const isMatch = params.request && params.request.method === method &&
        params.request.url.includes("/api/venues");
      if (!paused || !isMatch) {
        try {
          await cdp.send("Fetch.continueRequest", { requestId: params.requestId });
        } catch { /* 请求可能已失效，忽略 */ }
        return;
      }
      // 挂起时立即取回请求体原文：此时尚未放行，内容必然是点击保存那一刻的
      // 快照，之后页面怎么改都影响不到它。
      let body = null;
      try {
        const out = await cdp.send("Fetch.getRequestBody", { requestId: params.requestId });
        body = out.base64Encoded ? Buffer.from(out.body, "base64").toString("utf8") : out.body;
      } catch {
        body = params.request.postData || null;
      }
      const id = ++seq;
      held.set(id, { id, requestId: params.requestId, url: params.request.url, body, done: false });
      const ws = waiters;
      waiters = [];
      for (const w of ws) w(id);
    })().catch(() => { /* 竞态失败交给场景断言处理 */ });
  });

  return {
    async enable() {
      // 只在请求阶段暂停：continueRequest/fulfillRequest/failRequest 都可在
      // 该阶段使用，无需响应阶段的 continueResponse。
      await cdp.send("Fetch.enable", {
        patterns: [{ urlPattern: "*api/venues*", requestStage: "Request" }],
      });
    },
    pause() { paused = true; },
    resume() { paused = false; },
    pending() { return Array.from(held.values()).filter((r) => !r.done); },
    nextHold(timeout = 8000) {
      for (const rec of held.values()) {
        if (!rec.done) return Promise.resolve(rec.id);
      }
      return new Promise((resolve, reject) => {
        const timer = setTimeout(
          () => reject(new Error(`等待 ${method} /api/venues 被挂起超时`)), timeout);
        waiters.push((id) => { clearTimeout(timer); resolve(id); });
      });
    },
    bodyOf(id) {
      const rec = held.get(id);
      return rec ? rec.body : null;
    },
    // pass 放行到真实服务端，由真实处理链给出响应。
    async pass(id) {
      const rec = held.get(id);
      if (!rec || rec.done) return;
      rec.done = true;
      await cdp.send("Fetch.continueRequest", { requestId: rec.requestId });
    },
    // fulfill 不接触真实服务端，直接合成一个响应，保证内容与时机完全可控
    // （失败的读取不会读到真实数据，也不会在服务端落地任何记录）。
    async fulfill(id, status, payload, extraHeaders) {
      const rec = held.get(id);
      if (!rec || rec.done) return;
      rec.done = true;
      const raw = typeof payload === "string" ? payload : JSON.stringify(payload);
      const headers = [
        { name: "Content-Type", value: "application/json; charset=utf-8" },
        { name: "Content-Length", value: String(Buffer.byteLength(raw)) },
      ];
      for (const [name, value] of Object.entries(extraHeaders || {})) {
        headers.push({ name, value: String(value) });
      }
      await cdp.send("Fetch.fulfillRequest", {
        requestId: rec.requestId,
        responseCode: status,
        responseHeaders: headers,
        body: Buffer.from(raw, "utf8").toString("base64"),
      });
    },
    // fail 直接以网络错误终止该请求，模拟连接失败（fetch promise reject）。
    async fail(id, reason) {
      const rec = held.get(id);
      if (!rec || rec.done) return;
      rec.done = true;
      try {
        await cdp.send("Fetch.failRequest", {
          requestId: rec.requestId,
          errorReason: reason || "Failed",
        });
      } catch { /* 请求可能已失效 */ }
    },
    // continueAll 放行所有仍挂着的请求：场景中断时自愈，避免遗留 fetch 永久
    // 挂起影响后续场景。
    async continueAll() {
      for (const rec of held.values()) {
        if (!rec.done) {
          rec.done = true;
          try {
            await cdp.send("Fetch.continueRequest", { requestId: rec.requestId });
          } catch { /* ignore */ }
        }
      }
    },
  };
}

function createPostGate(cdp) { return createApiGate(cdp, "POST"); }
function createGetGate(cdp) { return createApiGate(cdp, "GET"); }

