    check("浏览器", "交互过程无页面脚本异常", pageErrors.length === 0,
      pageErrors.join("\n"));

    process.stdout.write(JSON.stringify({
      harnessError: null,
      browser: chrome.browserInfo.Browser,
      checks,
    }) + "\n");
  } finally {
    if (cdp) cdp.close();
    chrome.cleanup();
  }
